def ref_solve(A, k=5):
    N=A.shape[0]; v0=np.ones(N,dtype=A.dtype)
    ev,evc = sparse.linalg.eigs(A,k=k,v0=v0,maxiter=N*200,ncv=20)
    pairs=sorted(zip(ev,evc.T),key=lambda p:-abs(p[0]))
    return np.array([p[0] for p in pairs]), np.array([p[1] for p in pairs])

def test_solve(A, k=5, **kw):
    N=A.shape[0]; v0=np.ones(N,dtype=A.dtype)
